// index.ts
/** Copies `content` to the clipboard, which can be text, images or an array of these */
async function clippie(content, { reject } = {}) {
	try {
		const entries = {};
		for (const c of [].concat(content)) entries[c.type || "text/plain"] = c;
		const text = entries["text/plain"];
		const { clipboard } = navigator;
		if (typeof text === "string" && Object.keys(entries).length === 1) {
			if (!clipboard?.writeText) return fallback(text);
			try {
				await clipboard.writeText(text);
				return true;
			} catch {
				return fallback(text);
			}
		}
		if (!window.ClipboardItem || !clipboard?.write) return false;
		await clipboard.write([new ClipboardItem(Object.fromEntries(Object.entries(entries).map(([type, c]) => [type, new Blob([c], { type })])))]);
		return true;
	} catch (err) {
		if (reject) throw err;
		return false;
	}
}
function fallback(text) {
	const d = document;
	const copy = () => d.execCommand("copy");
	let copied = false;
	const onCopy = (e) => {
		e.stopImmediatePropagation();
		e.preventDefault();
		e.clipboardData.setData("text/plain", text);
		copied = true;
	};
	d.addEventListener("copy", onCopy, { capture: true });
	try {
		copy();
		if (copied) return true;
		const active = d.activeElement;
		const el = d.createElement("textarea");
		el.value = text;
		el.readOnly = true;
		el.style.cssText = "position:fixed;top:0;clip-path:inset(50%);font-size:12pt;white-space:pre";
		el.ariaHidden = "true";
		(active?.closest(":modal") ?? d.querySelector(":modal") ?? d.body).append(el);
		try {
			el.select();
			el.setSelectionRange(0, text.length);
			return copy() || copied;
		} finally {
			el.remove();
			active?.focus({ preventScroll: true });
		}
	} finally {
		d.removeEventListener("copy", onCopy, { capture: true });
	}
}

export { clippie };